window.PORTFOLIO_PROJECTS = [{"id":"adapta-solva","title":"Adapta Solva","description":"The larger version of Adapta Solva Legacy, where I handelled sound design, original music composition, FMOD implementation, and the organization of the game's audio pipeline alongside my studies. Developed a substantially more advanced dynamic music system, rebuilt and expanded earlier audio work for the new production, and organised work for 2 friends to help with.","hasMoreDescription":false,"context":"Para Fauna","role":"Technical Sound Designer","status":"active","collection":"Professional","disciplines":["Game Audio","Audio Implementation","Music"],"skills":["Sound Design","FMOD Implementation","Dynamic Music","Music Composition","Audio Implementation","Audio Project Organization","Audio Mixing"],"technologies":["FMOD","Unity"],"tools":[],"concepts":[],"relevantFor":["Technical Sound Designer","Game Audio Designer","Sound Designer","Audio Implementer","Composer"],"quality":"excellent","qualityRank":5,"videos":[{"label":"Demo Release Trailer","url":"https://www.youtube.com/watch?v=k6Y1jbk_pnM","type":"youtube","youtubeId":"k6Y1jbk_pnM"},{"label":"Music System Demo","url":"https://youtu.be/siz0wwhqv5o","type":"youtube","youtubeId":"siz0wwhqv5o"}],"links":[{"label":"Steam","url":"https://store.steampowered.com/app/4104680/Adapta_Solva/","type":"link","youtubeId":null}],"images":[],"descriptionSummaryHtml":"The larger version of <strong><a href=\"?filter=projects%3AAdapta+Solva+Legacy\">Adapta Solva Legacy</a></strong>, where I handelled sound design, original music composition, FMOD implementation, and the organization of the game&#039;s audio pipeline alongside my studies. Developed a substantially more advanced dynamic music system, rebuilt and expanded earlier audio work for the new production, and organised work for 2 friends to help with.","descriptionHtml":"<p>The larger version of <strong><a href=\"?filter=projects%3AAdapta+Solva+Legacy\">Adapta Solva Legacy</a></strong>, where I handelled sound design, original music composition, FMOD implementation, and the organization of the game&#039;s audio pipeline alongside my studies. Developed a substantially more advanced dynamic music system, rebuilt and expanded earlier audio work for the new production, and organised work for 2 friends to help with.</p>"},{"id":"grad-work-data-vs-objects-unity-audio-pipelines-compared","title":"Grad Work - DATA VS OBJECTS UNITY AUDIO PIPELINES COMPARED","description":"Designed and evaluated a custom data-oriented Unity audio system built with ECS and the Scriptable Audio Pipeline, including a custom ECS Root Output capable of rendering large numbers of voices independently of the GameObject hierarchy. Benchmarked the system against Unity's traditional GameObject-based audio pipeline and found consistently lower Audio CPU usage, improved scalability, and greater real-time stability under…","hasMoreDescription":true,"context":"MTS5 - Gradwork","role":"Audio Programmer","status":"complete","collection":"Education","disciplines":["Audio Programming","Game Audio"],"skills":["Audio Systems Design","Performance Profiling","Audio Programming","Technical Research"],"technologies":["Unity","Unity ECS","Scriptable Audio Pipeline"],"tools":[],"concepts":["Data-Oriented Design","Entity Component System (ECS)"],"relevantFor":["Audio Programmer","Game Audio Programmer","Audio Software Developer","Technical Sound Designer"],"quality":"excellent","qualityRank":5,"videos":[{"label":"YouTube","url":"https://youtu.be/JaOiaAYL-XI","type":"youtube","youtubeId":"JaOiaAYL-XI"}],"links":[{"label":"GitHub","url":"https://github.com/matthiaspeene/DataOrientedAudio/tree/main/Assets","type":"link","youtubeId":null}],"images":[{"target":"Design Plan.png","label":"Design Plan","type":"image","url":"../assets/evidence/443bdd0c63b37101.png"}],"descriptionSummaryHtml":"Designed and evaluated a custom data-oriented Unity audio system built with ECS and the Scriptable Audio Pipeline, including a custom ECS Root Output capable of rendering large numbers of voices independently of the GameObject hierarchy. Benchmarked the system against Unity&#039;s traditional GameObject-based audio pipeline and found consistently lower Audio CPU usage, improved scalability, and greater real-time stability under…","descriptionHtml":"<p>Designed and evaluated a custom data-oriented Unity audio system built with ECS and the Scriptable Audio Pipeline, including a custom ECS Root Output capable of rendering large numbers of voices independently of the GameObject hierarchy. Benchmarked the system against Unity&#039;s traditional GameObject-based audio pipeline and found consistently lower Audio CPU usage, improved scalability, and greater real-time stability under increasing audio workloads.</p>"},{"id":"sneakers","title":"Sneakers","description":"Created an FMOD proof of concept for a stealth game about a secret agent infiltrating a robot-infested spaceship. Designed simulated main-character, NPC, environment, and music systems that reacted to calm and alerted game states, supported by adaptive mixing, snapshots, sandbox testing, and profiler-based demonstration.","hasMoreDescription":true,"context":"MTS3 - Middleware 1","role":"Technical Sound Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Audio Implementation"],"skills":["FMOD Implementation","Interactive Audio Systems","Dynamic Music","Adaptive Mixing","Game Audio Prototyping","Audio State Management"],"technologies":["FMOD"],"tools":[],"concepts":[],"relevantFor":["Technical Sound Designer","Game Audio Designer","Audio Implementer","Sound Designer"],"quality":"excellent","qualityRank":5,"videos":[{"label":"YouTube","url":"https://youtu.be/zOlqgxBDris?si=ek_GE4_HjQ9ESYAs","type":"youtube","youtubeId":"zOlqgxBDris"}],"links":[],"images":[],"descriptionSummaryHtml":"Created an FMOD proof of concept for a stealth game about a secret agent infiltrating a robot-infested spaceship. Designed simulated main-character, NPC, environment, and music systems that reacted to calm and alerted game states, supported by adaptive mixing, snapshots, sandbox testing, and profiler-based demonstration.","descriptionHtml":"<p>Created an FMOD proof of concept for a stealth game about a secret agent infiltrating a robot-infested spaceship. Designed simulated main-character, NPC, environment, and music systems that reacted to calm and alerted game states, supported by adaptive mixing, snapshots, sandbox testing, and profiler-based demonstration.</p>\n<p>This also demonstrates the posibility of sketching a concept with sound. Like an audio concept artist.</p>"},{"id":"space-harbor-tycoon","title":"Space Harbor Tycoon","description":"Designed and implemented the complete audio palette for Space Harbor Tycoon in Wwise, creating a dynamic soundscape that evolved with player actions and camera position. Recorded original alien vocalizations and public announcement voice-overs, implemented adaptive crowd density and height-based mixing using RTPCs, and produced an immersive spaceport atmosphere with responsive ships, UI, ambience, and environmental audio.","hasMoreDescription":false,"context":"MTS3 - Middleware 2","role":"Technical Sound Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Audio Implementation"],"skills":["Wwise Implementation","Adaptive Audio","Interactive Audio Systems","Audio Mixing","RTPC Design","Field Recording"],"technologies":["Wwise"],"tools":[],"concepts":[],"relevantFor":["Technical Sound Designer","Game Audio Designer","Audio Implementer","Sound Designer"],"quality":"excellent","qualityRank":5,"videos":[{"label":"YouTube","url":"https://youtu.be/qQ-8B2fn2fI?si=OxRQSlWY_trMcpzF","type":"youtube","youtubeId":"qQ-8B2fn2fI"}],"links":[],"images":[],"descriptionSummaryHtml":"Designed and implemented the complete audio palette for <strong>Space Harbor Tycoon</strong> in Wwise, creating a dynamic soundscape that evolved with player actions and camera position. Recorded original alien vocalizations and public announcement voice-overs, implemented adaptive crowd density and height-based mixing using RTPCs, and produced an immersive spaceport atmosphere with responsive ships, UI, ambience, and environmental audio.","descriptionHtml":"<p>Designed and implemented the complete audio palette for <strong>Space Harbor Tycoon</strong> in Wwise, creating a dynamic soundscape that evolved with player actions and camera position. Recorded original alien vocalizations and public announcement voice-overs, implemented adaptive crowd density and height-based mixing using RTPCs, and produced an immersive spaceport atmosphere with responsive ships, UI, ambience, and environmental audio.</p>"},{"id":"space-racer","title":"Space Racer","description":"Composed and implemented a fully adaptive soundtrack for a futuristic space racing game using Wwise and original music written in Reaper and FL Studio. The music continuously responds to gameplay through real-time parameters, gameplay states, synchronized sound effects, and memory-efficient implementation techniques while maintaining seamless musical flow and variation.","hasMoreDescription":true,"context":"MTS4 - Music for Games","role":"Interactive Music Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Interactive Music"],"skills":["Interactive Music","Adaptive Music Design","Music Composition","Vertical Remixing","Horizontal Resequencing","Audio Systems Design","Music Optimization"],"technologies":["Wwise"],"tools":["Reaper"],"concepts":[],"relevantFor":["Interactive Music Designer","Game Composer","Technical Sound Designer","Game Audio Designer"],"quality":"excellent","qualityRank":5,"videos":[{"label":"Youtube","url":"https://youtu.be/WXdrmUwBF10?si=-GMnZIdSc020T2ZE","type":"youtube","youtubeId":"WXdrmUwBF10"}],"links":[],"images":[],"descriptionSummaryHtml":"Composed and implemented a fully adaptive soundtrack for a futuristic space racing game using Wwise and original music written in Reaper and FL Studio. The music continuously responds to gameplay through real-time parameters, gameplay states, synchronized sound effects, and memory-efficient implementation techniques while maintaining seamless musical flow and variation.","descriptionHtml":"<p>Composed and implemented a fully adaptive soundtrack for a futuristic space racing game using Wwise and original music written in Reaper and FL Studio. The music continuously responds to gameplay through real-time parameters, gameplay states, synchronized sound effects, and memory-efficient implementation techniques while maintaining seamless musical flow and variation.</p>\n<h5>Highlights</h5>\n<h6>Dynamic Parameters</h6>\n<ul><li><strong>Speed</strong> — Music intensity scales continuously with vehicle speed. At lower speeds the bass is reduced while drum hits become shorter through ADSR manipulation, creating the sensation that the energy of the music slows together with the player.</li></ul>\n<ul><li><strong>Collision</strong> — Crashes drive an ADSR-like gameplay parameter whose value depends on collision strength and gradually decays over time. This parameter feeds glitch-style delay effects, creating a dramatic musical interruption that naturally combines with the reduced intensity caused by the loss of speed, giving immediate musical feedback for impacts.</li></ul>\n<ul><li><strong>Gravity</strong> — Black holes influence a gravity parameter that modulates the pitch of the reverb, producing a shimmering effect that makes the soundtrack react organically to gravitational anomalies within the level.</li></ul>\n<h6>Music States</h6>\n<ul><li><strong>Section State</strong> — Different regions of the race trigger unique musical arrangements:</li><li>Standard racing section</li><li>Intense section with more aggressive instrumentation for technical asteroid tunnel segments</li><li>Gravity section designed around heavy use of the gravity parameter and spatial effects</li></ul>\n<ul><li><strong>Paused State</strong> — Pausing the game transitions the music into a slowed, filtered version by reducing the effective speed parameter to zero while applying additional low-pass filtering.</li></ul>\n<h6>Beat-Synchronised Gameplay</h6>\n<p>Gameplay sound effects were synchronized to the musical beat, ensuring that gameplay events remained rhythmically connected to the soundtrack rather than simply playing independently.</p>\n<h6>Memory Optimisation</h6>\n<p>The entire music system was designed with runtime efficiency in mind.</p>\n<ul><li>Drum performances were converted into sliced breakbeats triggered through MIDI inside Wwise instead of storing multiple rendered loops.</li><li>Approximately twelve drum variations were created using only a handful of short drum slices, dramatically reducing memory consumption.</li><li>Bass lines were generated using Wwise&#039;s internal synthesizer instead of prerecorded audio.</li><li>Musical phrases were intelligently reused and rearranged between sections to maximize variation without increasing asset size.</li></ul>\n<p>The resulting system occupies roughly the memory footprint of a single conventional music track while providing fully adaptive playback with effectively unlimited musical variation.</p>"},{"id":"spell-sound-design","title":"Spell Sound Design","description":"Redesigned two spell effects from Dragon's Dogma: High Thunder Mine (electric) and Maelstrom (fire meteors). Created original, layered magical effects by combining synthesis, processed recordings, and transformed source material into a cohesive cinematic spell soundscape.","hasMoreDescription":false,"context":"MTS3 - Sound 3","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Spell Sound Design","Sound Design","Synthesizer Programming","Layering","Audio Processing","Audio Mixing"],"technologies":[],"tools":["Reaper"],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Technical Sound Designer","Cinematic Sound Designer"],"quality":"excellent","qualityRank":5,"videos":[{"label":"Maelstrom","url":"https://youtu.be/TxzMSbe06TQ","type":"youtube","youtubeId":"TxzMSbe06TQ"},{"label":"HighThundermine","url":"https://youtu.be/r1GRWg0QzdY","type":"youtube","youtubeId":"r1GRWg0QzdY"}],"links":[],"images":[],"descriptionSummaryHtml":"Redesigned two spell effects from *Dragon&#039;s Dogma*: <strong>High Thunder Mine</strong> (electric) and <strong>Maelstrom</strong> (fire meteors). Created original, layered magical effects by combining synthesis, processed recordings, and transformed source material into a cohesive cinematic spell soundscape.","descriptionHtml":"<p>Redesigned two spell effects from *Dragon&#039;s Dogma*: <strong>High Thunder Mine</strong> (electric) and <strong>Maelstrom</strong> (fire meteors). Created original, layered magical effects by combining synthesis, processed recordings, and transformed source material into a cohesive cinematic spell soundscape.</p>"},{"id":"umbrellas-5-1-surround-mix","title":"Umbrellas 5.1 Surround Mix","description":"Created a 5.1 surround mix for Umbrellas in the Sun, using spatial positioning, automation, and effects to produce an immersive and balanced mix.","hasMoreDescription":true,"context":"MTS4 - Sound 4","role":"Mix Engineer","status":"complete","collection":"Education","disciplines":["Audio"],"skills":["Surround Mixing","Spatial Audio","Audio Automation","Sound Design"],"technologies":[],"tools":["Reaper","RME TotalMix"],"concepts":[],"relevantFor":["Sound Designer","Mix Engineer","Audio Engineer"],"quality":"excellent","qualityRank":5,"videos":[],"links":[{"label":"Download original 5.1 WAV  — 106 MB","url":"https://drive.google.com/file/d/1bvWdd_cVli-_rEN1qW84EerBP2or7-Nc/view?usp=sharing","type":"link","youtubeId":null},{"label":"Download original 5.1 VIDEO  —  444 MB","url":"https://drive.google.com/file/d/1cLGza2rWmFiTa9BMeMSvDqXq87aCMzM6/view?usp=sharing","type":"link","youtubeId":null}],"images":[{"target":"Preview1.jpg","label":"Preview1","type":"image","url":"../assets/evidence/077b86710fc58623.jpg"},{"target":"Preview2.jpg","label":"Preview2","type":"image","url":"../assets/evidence/2c67d10d82b42715.jpg"},{"target":"Preview3.jpg","label":"Preview3","type":"image","url":"../assets/evidence/aa2c119877b14712.jpg"},{"target":"Preview4.jpg","label":"Preview4","type":"image","url":"../assets/evidence/6f945f280f088d55.jpg"}],"descriptionSummaryHtml":"Created a 5.1 surround mix for <a href=\"?filter=projects%3AUmbrellas+in+the+Sun\">Umbrellas in the Sun</a>, using spatial positioning, automation, and effects to produce an immersive and balanced mix.","descriptionHtml":"<p>Created a 5.1 surround mix for <a href=\"?filter=projects%3AUmbrellas+in+the+Sun\">Umbrellas in the Sun</a>, using spatial positioning, automation, and effects to produce an immersive and balanced mix.</p>\n<h5>Techniques Used</h5>\n<p>I spatialized the audio using reapers own spatialization tools routing audio to the corresponding channels. For extra immersion I also spatialized the reverb. During the thunder I made the echo of the thunder travel around the listener to give the sound extra size. Lastly I used spatialized layering, under the umbrella I had 1 hard panned umbrella rain layer for example and a broad rain layer. It&#039;s important to spatialize the ambience to make the space feel real.</p>"},{"id":"umbrellas-in-the-sun","title":"Umbrellas in the Sun","description":"Created the complete sound design and final mix for the animated short Umbrellas in the Sun, collaborating closely with an animation team and a conservatory composer. Iterated extensively with the team to refine key sounds such as the thunder, integrated orchestral recording stems into the mix, and delivered production-ready assets on schedule while coordinating expectations across multiple disciplines.","hasMoreDescription":false,"context":"MTS3 - Sound Integration 1","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Audio"],"skills":["Sound Design","Audio Mixing","Collaboration","Asset Delivery","Music Integration","Audio Production","Stakeholder Communication","Audio Editing"],"technologies":[],"tools":["Reaper"],"concepts":[],"relevantFor":["Sound Designer","Mix Engineer","Technical Sound Designer","Game Audio Designer"],"quality":"excellent","qualityRank":5,"videos":[{"label":"YouTube","url":"https://youtu.be/SNGk1JnOUqk?si=aK-X0wLdwHRLIRqU","type":"youtube","youtubeId":"SNGk1JnOUqk"}],"links":[],"images":[],"descriptionSummaryHtml":"Created the complete sound design and final mix for the animated short <strong>Umbrellas in the Sun</strong>, collaborating closely with an animation team and a conservatory composer. Iterated extensively with the team to refine key sounds such as the thunder, integrated orchestral recording stems into the mix, and delivered production-ready assets on schedule while coordinating expectations across multiple disciplines.","descriptionHtml":"<p>Created the complete sound design and final mix for the animated short <strong>Umbrellas in the Sun</strong>, collaborating closely with an animation team and a conservatory composer. Iterated extensively with the team to refine key sounds such as the thunder, integrated orchestral recording stems into the mix, and delivered production-ready assets on schedule while coordinating expectations across multiple disciplines.</p>"},{"id":"unity-granular-synth","title":"Unity Granular Synth","description":"Created a granular synth package in Unity using the scriptable audio pipeline. The synth was made using data oriented principles for performance. It uses a custom Unity UI on a scriptable object to make configuration easy.","hasMoreDescription":true,"context":"MTS4 - Audiolab","role":"Audio Programmer","status":"complete","collection":"Personal","disciplines":["Audio Programming","Interactive Audio","Music Technology"],"skills":["Audio Plugin Development","Audio Programming","Unity Development","Unity Plugin Development"],"technologies":["Unity"],"tools":[],"concepts":["Granular Synthesis","Data-Oriented Design","Scriptable Audio Pipeline"],"relevantFor":["Audio Programmer","Audio Software Developer","DSP Engineer","Technical Sound Designer"],"quality":"excellent","qualityRank":5,"videos":[{"label":"YouTube","url":"https://youtu.be/ev3UDn1Lr18?si=Y_Z4-cFAbL5eNFfC","type":"youtube","youtubeId":"ev3UDn1Lr18"}],"links":[{"label":"Package","url":"https://marketplace.unity.com/packages/tools/granular-synth-3703711","type":"link","youtubeId":null}],"images":[],"descriptionSummaryHtml":"Created a granular synth package in Unity using the scriptable audio pipeline. The synth was made using data oriented principles for performance. It uses a custom Unity UI on a scriptable object to make configuration easy.","descriptionHtml":"<p>Created a granular synth package in Unity using the scriptable audio pipeline. The synth was made using data oriented principles for performance. It uses a custom Unity UI on a scriptable object to make configuration easy.</p>\n<p><strong>Features:</strong></p>\n<ul><li>Granular Synth, configurable as a ScriptableObject.</li><li>Controls: Rate, Playback Position Range, Pitch Range, Volume Range, Pan Range, Grain Size Range.</li><li>Configurable Grain Shape.</li><li>Stereo Sample Support.</li><li>Live Preview.</li><li>Toggle-able Anti-Phasing.</li><li>Modulation Matrix for easily assigning multi parameter changes.</li></ul>"},{"id":"anno-trailer-music-edit","title":"Anno Trailer Music Edit","description":"Researched, selected, and edited orchestral music to create a new soundtrack for the Anno 1800 trailer. Synchronized the music to the trailer's pacing, mixed it with the original voice-over, and analyzed the musical choices to support the game's historical atmosphere.","hasMoreDescription":false,"context":"MTS4 - Music for Games","role":"Interactive Music Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Interactive Music"],"skills":["Music Editing","Music Supervision","Trailer Music Editing","Musical Analysis","Audio Mixing"],"technologies":[],"tools":["Reaper"],"concepts":[],"relevantFor":["Interactive Music Designer","Game Audio Designer","Music Editor","Sound Designer"],"quality":"strong","qualityRank":4,"videos":[{"label":"YouTube","url":"https://youtu.be/NTmlbj92EAk","type":"youtube","youtubeId":"NTmlbj92EAk"}],"links":[],"images":[],"descriptionSummaryHtml":"Researched, selected, and edited orchestral music to create a new soundtrack for the *Anno 1800* trailer. Synchronized the music to the trailer&#039;s pacing, mixed it with the original voice-over, and analyzed the musical choices to support the game&#039;s historical atmosphere.","descriptionHtml":"<p>Researched, selected, and edited orchestral music to create a new soundtrack for the *Anno 1800* trailer. Synchronized the music to the trailer&#039;s pacing, mixed it with the original voice-over, and analyzed the musical choices to support the game&#039;s historical atmosphere.</p>"},{"id":"beats-from-the-deep","title":"Beats From the Deep","description":"Developed the audio systems for Beats from the Deep, a four-player cooperative rhythm game in which players work together to defeat a cosmic horror boss. Composed the music, designed the sound effects, programmed a custom DSP-driven rhythm system in Unreal Engine that exposed timing events to gameplay systems, and authored the project's Sound Bible while contributing to the broader technical documentation.","hasMoreDescription":false,"context":"MTS4 - Game Projects","role":"Technical Sound Designer","status":"complete","collection":"Education","disciplines":["Game Development","Game Audio","Audio Programming"],"skills":["Audio Programming","Music Composition","Sound Design","Rhythm System Development","Unreal Engine Development","Technical Documentation","Agile Development"],"technologies":["Unreal Engine 5","C++"],"tools":["P4V","HacknPlan"],"concepts":[],"relevantFor":["Technical Sound Designer","Audio Programmer","Gameplay Programmer","Game Audio Designer"],"quality":"strong","qualityRank":4,"videos":[{"label":"Trailer","url":"https://youtu.be/VdTjcHlZi-M?si=LA1cCuAdvzUmQQX6","type":"youtube","youtubeId":"VdTjcHlZi-M"},{"label":"Song - Youtube","url":"https://www.youtube.com/watch?v=mQ5pfvzBCjk","type":"youtube","youtubeId":"mQ5pfvzBCjk"}],"links":[{"label":"Itch.io","url":"https://matthiaspeene.itch.io/beatsfromthedeep","type":"link","youtubeId":null},{"label":"Spotify","url":"https://open.spotify.com/track/7KKYKuDI19gEslgAfRcWcQ?si=2d041d4cfdbd4d5c","type":"link","youtubeId":null}],"images":[],"descriptionSummaryHtml":"Developed the audio systems for <strong>Beats from the Deep</strong>, a four-player cooperative rhythm game in which players work together to defeat a cosmic horror boss. Composed the music, designed the sound effects, programmed a custom DSP-driven rhythm system in Unreal Engine that exposed timing events to gameplay systems, and authored the project&#039;s <strong>Sound Bible</strong> while contributing to the broader technical documentation.","descriptionHtml":"<p>Developed the audio systems for <strong>Beats from the Deep</strong>, a four-player cooperative rhythm game in which players work together to defeat a cosmic horror boss. Composed the music, designed the sound effects, programmed a custom DSP-driven rhythm system in Unreal Engine that exposed timing events to gameplay systems, and authored the project&#039;s <strong>Sound Bible</strong> while contributing to the broader technical documentation.</p>"},{"id":"close-combat-sound-design","title":"Close Combat Sound Design","description":"Redesigned a close-combat sequence from Mortal Kombat X featuring Tremor and Triborg using only original recordings and synthesis. Built reusable combat assets triggered through a MIDI-driven system with intensity parameters to demonstrate a dynamic workflow suitable for real-time game audio implementation rather than linear foley.","hasMoreDescription":false,"context":"MTS3 - Sound 3","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Combat Sound Design","Foley Recording","Vocal Sound Design","Procedural Audio Design","MIDI Implementation","Audio Mixing"],"technologies":[],"tools":["Reaper"],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Technical Sound Designer","Foley Artist"],"quality":"strong","qualityRank":4,"videos":[{"label":"YouTube","url":"https://youtu.be/MmCYLgQF4n8","type":"youtube","youtubeId":"MmCYLgQF4n8"}],"links":[],"images":[],"descriptionSummaryHtml":"Redesigned a close-combat sequence from *Mortal Kombat X* featuring Tremor and Triborg using only original recordings and synthesis. Built reusable combat assets triggered through a MIDI-driven system with intensity parameters to demonstrate a dynamic workflow suitable for real-time game audio implementation rather than linear foley.","descriptionHtml":"<p>Redesigned a close-combat sequence from *Mortal Kombat X* featuring Tremor and Triborg using only original recordings and synthesis. Built reusable combat assets triggered through a MIDI-driven system with intensity parameters to demonstrate a dynamic workflow suitable for real-time game audio implementation rather than linear foley.</p>"},{"id":"creature-sound-design","title":"Creature Sound Design","description":"Redesigned the audio for Hræzlyr, the dragon from God of War, creating original creature vocalizations and foley synchronized to gameplay footage. Combined recorded source material, layered processing, and custom movement sounds into a cohesive cinematic soundscape with a polished final mix.","hasMoreDescription":true,"context":"MTS3 - Sound 3","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Creature Sound Design","Vocal Sound Design","Foley Recording","Sound Design","Audio Mixing","Layering"],"technologies":[],"tools":["Reaper"],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Creature Sound Designer","Audio Engineer"],"quality":"strong","qualityRank":4,"videos":[{"label":"YouTube","url":"https://youtu.be/clwDGbqRaEc?si=kzsV1uZVYsdOb7eP","type":"youtube","youtubeId":"clwDGbqRaEc"}],"links":[],"images":[],"descriptionSummaryHtml":"Redesigned the audio for <strong>Hræzlyr</strong>, the dragon from *God of War*, creating original creature vocalizations and foley synchronized to gameplay footage. Combined recorded source material, layered processing, and custom movement sounds into a cohesive cinematic soundscape with a polished final mix.","descriptionHtml":"<p>Redesigned the audio for <strong>Hræzlyr</strong>, the dragon from *God of War*, creating original creature vocalizations and foley synchronized to gameplay footage. Combined recorded source material, layered processing, and custom movement sounds into a cohesive cinematic soundscape with a polished final mix.</p>\n<h5>Highlights</h5>\n<ul><li>Recorded myself and my friend doing inhale screams as dragon layers.</li><li>Used panned granular synthesis for the gravel flying past.</li><li>Used granular triggered layering technique as a layer for the foley footsteps.</li></ul>"},{"id":"ellen-on-a-strange-planet-fmod","title":"Ellen on a Strange Planet (FMOD)","description":"Implemented the complete audio experience for Ellen on a Strange Planet, integrating all gameplay, UI, ambient, and enemy audio into an existing game build using FMOD. Created a polished interactive mix with adaptive reverb, spatial audio, optimized event structures, and responsive gameplay-driven audio systems suitable for a production-quality game prototype.","hasMoreDescription":true,"context":"MTS3 - Middleware 1","role":"Technical Sound Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Audio Implementation"],"skills":["FMOD Implementation","Interactive Audio Systems","Spatial Audio","Adaptive Mixing","Audio Optimization","Game Audio Integration"],"technologies":["FMOD"],"tools":[],"concepts":[],"relevantFor":["Technical Sound Designer","Game Audio Designer","Audio Implementer","Sound Designer"],"quality":"strong","qualityRank":4,"videos":[{"label":"Youtube","url":"https://youtu.be/VPvLwMprJls","type":"youtube","youtubeId":"VPvLwMprJls"}],"links":[],"images":[],"descriptionSummaryHtml":"Implemented the complete audio experience for <strong>Ellen on a Strange Planet</strong>, integrating all gameplay, UI, ambient, and enemy audio into an existing game build using FMOD. Created a polished interactive mix with adaptive reverb, spatial audio, optimized event structures, and responsive gameplay-driven audio systems suitable for a production-quality game prototype.","descriptionHtml":"<p>Implemented the complete audio experience for <strong>Ellen on a Strange Planet</strong>, integrating all gameplay, UI, ambient, and enemy audio into an existing game build using FMOD. Created a polished interactive mix with adaptive reverb, spatial audio, optimized event structures, and responsive gameplay-driven audio systems suitable for a production-quality game prototype.</p>\n<h6>Highlights</h6>\n<ul><li>Dynamic Music System</li><li>Reverb Regions</li><li>I listened to a slowed down version of jungle birds, then imitated those sounds with my own voice and sped my voice up. This gave me new clean alien bird sounds for the ambiance system.</li></ul>"},{"id":"emotions-platformer","title":"Emotions Platformer","description":"Designed and developed a 2D puzzle platformer prototype centered around emotions as playable characters, each with unique movement and puzzle-solving abilities. Implemented the core gameplay systems in Unity, including character switching, emotion attraction and repulsion mechanics, checkpoints, platforming abilities, and progression through puzzle-based levels.","hasMoreDescription":false,"context":"MTS3 - Game Engine Fundamentals","role":"Gameplay Programmer","status":"complete","collection":"Education","disciplines":["Game Development","Gameplay Programming"],"skills":["Gameplay Programming","Unity Development","Puzzle Design","Platformer Development","C Sharp Programming","Game Systems Design"],"technologies":["Unity","C Sharp"],"tools":[],"concepts":[],"relevantFor":["Gameplay Programmer","Unity Developer","Game Programmer","Technical Game Designer"],"quality":"strong","qualityRank":4,"videos":[],"links":[{"label":"Itch.io","url":"https://matthiaspeene.itch.io/colourfull-emotions","type":"link","youtubeId":null}],"images":[{"target":"PlayBanner.png","label":"PlayBanner","type":"image","url":"../assets/evidence/63d835cf1ad4fd3b.png"}],"descriptionSummaryHtml":"Designed and developed a 2D puzzle platformer prototype centered around emotions as playable characters, each with unique movement and puzzle-solving abilities. Implemented the core gameplay systems in Unity, including character switching, emotion attraction and repulsion mechanics, checkpoints, platforming abilities, and progression through puzzle-based levels.","descriptionHtml":"<p>Designed and developed a 2D puzzle platformer prototype centered around emotions as playable characters, each with unique movement and puzzle-solving abilities. Implemented the core gameplay systems in Unity, including character switching, emotion attraction and repulsion mechanics, checkpoints, platforming abilities, and progression through puzzle-based levels.</p>"},{"id":"into-the-deep","title":"Into the Deep","description":"Developed the core rhythm and dynamic music systems for Into the Deep, a top-down isometric rhythm-based roguelike where enemy behavior synchronizes with the music. Built the system in Unreal Engine using C++ and MetaSounds, exposed instrument-specific rhythm events to gameplay programmers, implemented adaptive music for boss encounters, designed and integrated sound effects, and contributed to the composition and mix.","hasMoreDescription":false,"context":"Group Projects","role":"Technical Sound Designer","status":"complete","collection":"Education","disciplines":["Game Development","Game Audio","Audio Programming"],"skills":["Audio Programming","Dynamic Music","Rhythm System Development","Sound Design","Audio Implementation","Music Mixing","Unreal Engine Development"],"technologies":["Unreal Engine 5","C++","MetaSounds"],"tools":[],"concepts":[],"relevantFor":["Technical Sound Designer","Audio Programmer","Game Audio Designer","Gameplay Programmer"],"quality":"strong","qualityRank":4,"videos":[{"label":"Trailer","url":"https://www.youtube.com/watch?v=dLD2hP4zKM4","type":"youtube","youtubeId":"dLD2hP4zKM4"}],"links":[{"label":"Steam","url":"https://store.steampowered.com/app/4612780/Into_The_Deep/","type":"link","youtubeId":null}],"images":[],"descriptionSummaryHtml":"Developed the core rhythm and dynamic music systems for <strong><a href=\"?filter=projects%3AInto+the+Deep\">Into the Deep</a></strong>, a top-down isometric rhythm-based roguelike where enemy behavior synchronizes with the music. Built the system in Unreal Engine using C++ and MetaSounds, exposed instrument-specific rhythm events to gameplay programmers, implemented adaptive music for boss encounters, designed and integrated sound effects, and contributed to the composition and mix.","descriptionHtml":"<p>Developed the core rhythm and dynamic music systems for <strong><a href=\"?filter=projects%3AInto+the+Deep\">Into the Deep</a></strong>, a top-down isometric rhythm-based roguelike where enemy behavior synchronizes with the music. Built the system in Unreal Engine using C++ and MetaSounds, exposed instrument-specific rhythm events to gameplay programmers, implemented adaptive music for boss encounters, designed and integrated sound effects, and contributed to the composition and mix.</p>"},{"id":"john-lemon","title":"John Lemon","description":"Implemented a complete audio system for the John Lemon Unity project, integrating sound effects, music, and spatial audio while creating additional gameplay features. Expanded the game's audio experience by programming new interactive systems, implementing custom sound behaviour, and balancing the mix using Unity's built-in audio tools.","hasMoreDescription":true,"context":"MTS2 - Audio Implementation","role":"Technical Sound Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Audio Programming"],"skills":["Audio Implementation","Unity Audio","Audio Mixing","Spatial Audio","Audio Systems Design","Sound Design","C Sharp Programming","Music Composition"],"technologies":["Unity","C Sharp"],"tools":["Unity Audio Mixer"],"concepts":[],"relevantFor":["Technical Sound Designer","Game Audio Programmer","Audio Programmer","Sound Designer","Composer"],"quality":"strong","qualityRank":4,"videos":[{"label":"Youtube","url":"https://www.youtube.com/watch?v=QqSboUd9BHU","type":"youtube","youtubeId":"QqSboUd9BHU"}],"links":[],"images":[],"descriptionSummaryHtml":"Implemented a complete audio system for the John Lemon Unity project, integrating sound effects, music, and spatial audio while creating additional gameplay features. Expanded the game&#039;s audio experience by programming new interactive systems, implementing custom sound behaviour, and balancing the mix using Unity&#039;s built-in audio tools.","descriptionHtml":"<p>Implemented a complete audio system for the John Lemon Unity project, integrating sound effects, music, and spatial audio while creating additional gameplay features. Expanded the game&#039;s audio experience by programming new interactive systems, implementing custom sound behaviour, and balancing the mix using Unity&#039;s built-in audio tools.</p>\n<h5>Highlights</h5>\n<ul><li>Different sounds for different surfaces</li><li>Wrote music based on Abigale</li><li>Ghost sings together with the music (0:29)</li><li>Created own scriptable audio object for audio randomization</li><li>Use of reverb zones</li></ul>"},{"id":"lego-databasing","title":"LEGO - Databasing","description":"Developed an internal code-to-database automation tool during my internship at LEGO Design that scanned a codebase with Python and generated an SQLite database. Also created a lightweight browser for exploring the generated data, reducing manual organization work.","hasMoreDescription":true,"context":"Internship","role":"Software Developer","status":"complete","collection":"Professional","disciplines":["Software Development","Developer Tools"],"skills":["Python Programming","Database Design","Codebase Analysis","Automation","Tool Development"],"technologies":["Python","SQLite"],"tools":[],"concepts":[],"relevantFor":["Software Developer","Tools Programmer","Technical Developer"],"quality":"strong","qualityRank":4,"videos":[],"links":[],"images":[{"target":"LEGO.jpg","label":"LEGO","type":"image","url":"../assets/evidence/2d987d06dcc4be90.jpg"}],"descriptionSummaryHtml":"Developed an internal code-to-database automation tool during my internship at LEGO Design that scanned a codebase with Python and generated an SQLite database. Also created a lightweight browser for exploring the generated data, reducing manual organization work.","descriptionHtml":"<p>Developed an internal code-to-database automation tool during my internship at LEGO Design that scanned a codebase with Python and generated an SQLite database. Also created a lightweight browser for exploring the generated data, reducing manual organization work.</p>\n<p>*For more information, reach out to designtalent@lego.com.</p>"},{"id":"lego-psycho-acoustic-analysis","title":"LEGO - Psycho-acoustic Analysis","description":"Developed a mass audio-analysis tool during an internship at LEGO Design that could process hundreds of audio files and evaluate characteristics including loudness, sharpness, and frequency content to support comparison of sound quality. Built the analysis pipeline in Python using MOSQITO, stored results in SQLite, and created a lightweight HTML browser for exploring the analyzed data.","hasMoreDescription":true,"context":"Internship","role":"Audio Programmer","status":"complete","collection":"Professional","disciplines":["Audio Programming","Software Development"],"skills":["Audio Analysis","Python Programming","Psychoacoustic Analysis","Database Design","Automation","Data Visualization"],"technologies":["Python","MOSQITO","SQLite","HTML"],"tools":[],"concepts":[],"relevantFor":["Audio Programmer","Audio Software Developer","Tools Programmer","Audio Engineer"],"quality":"strong","qualityRank":4,"videos":[],"links":[],"images":[{"target":"LEGO.jpg","label":"LEGO","type":"image","url":"../assets/evidence/2d987d06dcc4be90.jpg"}],"descriptionSummaryHtml":"Developed a mass audio-analysis tool during an internship at LEGO Design that could process hundreds of audio files and evaluate characteristics including loudness, sharpness, and frequency content to support comparison of sound quality. Built the analysis pipeline in Python using MOSQITO, stored results in SQLite, and created a lightweight HTML browser for exploring the analyzed data.","descriptionHtml":"<p>Developed a mass audio-analysis tool during an internship at LEGO Design that could process hundreds of audio files and evaluate characteristics including loudness, sharpness, and frequency content to support comparison of sound quality. Built the analysis pipeline in Python using MOSQITO, stored results in SQLite, and created a lightweight HTML browser for exploring the analyzed data.</p>\n<p>*For more information, reach out to designtalent@lego.com.</p>"},{"id":"lego-ui-sound-design","title":"LEGO - UI Sound Design","description":"Contributed UI sound design for a LEGO application, creating interface audio to support user interaction and feedback within the app.","hasMoreDescription":true,"context":"Internship","role":"Sound Designer","status":"complete","collection":"Professional","disciplines":["Game Audio","Interactive Audio"],"skills":["UI Sound Design","Sound Design","Interactive Audio"],"technologies":[],"tools":[],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Technical Sound Designer"],"quality":"strong","qualityRank":4,"videos":[],"links":[],"images":[{"target":"LEGO.jpg","label":"LEGO","type":"image","url":"../assets/evidence/2d987d06dcc4be90.jpg"}],"descriptionSummaryHtml":"Contributed UI sound design for a LEGO application, creating interface audio to support user interaction and feedback within the app.","descriptionHtml":"<p>Contributed UI sound design for a LEGO application, creating interface audio to support user interaction and feedback within the app.</p>\n<p>*For more information, reach out to designtalent@lego.com.</p>"},{"id":"ohm","title":"Ohm","description":"Created the complete sound design and final mix for the animated short Ohm, combining ambience, foley, sound effects, and extensively edited production music into a cohesive soundtrack. Processed and synchronized existing music to the animation through granular effects, spatial processing, and evolving instrumentation to reinforce the film's abstract narrative and emotional progression.","hasMoreDescription":false,"context":"MTS3 - Sound Integration 1","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Sound Design","Audio Mixing","Music Editing","Music Synchronization","Audio Production","Creative Audio Processing","Granular Audio Processing"],"technologies":[],"tools":["Reaper"],"concepts":[],"relevantFor":["Sound Designer","Mix Engineer","Game Audio Designer","Audio Editor"],"quality":"strong","qualityRank":4,"videos":[{"label":"YouTube","url":"https://youtu.be/T7iZfOwwqAw","type":"youtube","youtubeId":"T7iZfOwwqAw"}],"links":[],"images":[],"descriptionSummaryHtml":"Created the complete sound design and final mix for the animated short <strong>Ohm</strong>, combining ambience, foley, sound effects, and extensively edited production music into a cohesive soundtrack. Processed and synchronized existing music to the animation through granular effects, spatial processing, and evolving instrumentation to reinforce the film&#039;s abstract narrative and emotional progression.","descriptionHtml":"<p>Created the complete sound design and final mix for the animated short <strong>Ohm</strong>, combining ambience, foley, sound effects, and extensively edited production music into a cohesive soundtrack. Processed and synchronized existing music to the animation through granular effects, spatial processing, and evolving instrumentation to reinforce the film&#039;s abstract narrative and emotional progression.</p>"},{"id":"rain-granular-synth","title":"Rain Granular Synth","description":"Designed and developed Grainy Day, a New Interface for Musical Expression (NIME) consisting of a JUCE-based granular synthesizer controlled wirelessly via OSC from a custom Unity mobile application. Researched, documented, and presented the project in the format of an academic NIME paper, demonstrating the use of data-oriented design and multithreading to achieve responsive real-time granular synthesis.","hasMoreDescription":false,"context":"MTS4 - Audiolab","role":"Audio Programmer","status":"complete","collection":"Education","disciplines":["Audio Programming","Interactive Audio","Music Technology"],"skills":["Audio Plugin Development","OSC Communication","Multithreaded Programming","Technical Research","Technical Writing"],"technologies":["JUCE","C++","Unity","OSC"],"tools":["Zotero"],"concepts":["Granular Synthesis","Data-Oriented Design"],"relevantFor":["Audio Programmer","Audio Software Developer","DSP Engineer","Technical Sound Designer"],"quality":"strong","qualityRank":4,"videos":[],"links":[],"images":[{"target":"Fig 1. Simplified Overview.png","label":"Fig 1. Simplified Overview","type":"image","url":"../assets/evidence/5b934097887f9e4f.png"},{"target":"Fig 2. Grain Scheduling.png","label":"Fig 2. Grain Scheduling","type":"image","url":"../assets/evidence/e5d10a0a9294914a.png"},{"target":"Fig 3. Thread Safety.png","label":"Fig 3. Thread Safety","type":"image","url":"../assets/evidence/50e7daf7701fec0d.png"}],"descriptionSummaryHtml":"Designed and developed <strong>Grainy Day</strong>, a New Interface for Musical Expression (NIME) consisting of a JUCE-based granular synthesizer controlled wirelessly via OSC from a custom Unity mobile application. Researched, documented, and presented the project in the format of an academic NIME paper, demonstrating the use of data-oriented design and multithreading to achieve responsive real-time granular synthesis.","descriptionHtml":"<p>Designed and developed <strong>Grainy Day</strong>, a New Interface for Musical Expression (NIME) consisting of a JUCE-based granular synthesizer controlled wirelessly via OSC from a custom Unity mobile application. Researched, documented, and presented the project in the format of an academic NIME paper, demonstrating the use of data-oriented design and multithreading to achieve responsive real-time granular synthesis.</p>"},{"id":"righter","title":"Righter","description":"Designed the complete soundscape for the short film Richter, creating every sound from scratch using original field recordings and synthesis without relying on commercial sound libraries. Produced a custom sound library with organized metadata alongside a polished cinematic mix featuring vehicles, environmental effects, impacts, drones, alarms, and other designed assets. For the voices we had to come up with our own story…","hasMoreDescription":true,"context":"MTS2 - Digital Audio Workstations 2","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Sound Design","Field Recording","Synthesizer Programming","Audio Mixing","Sound Library Creation","Layering","Music Composition","Voice Acting"],"technologies":["UCS Category System"],"tools":["Reaper","Vital","ReaSynth","TAL-NoiseMaker"],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Technical Sound Designer","Field Recordist","Composer"],"quality":"strong","qualityRank":4,"videos":[{"label":"SFX Only","url":"https://youtu.be/ZoyKUUrP9_g?si=LLjA2v5J3g3cEekY","type":"youtube","youtubeId":"ZoyKUUrP9_g"},{"label":"Full Video","url":"https://www.youtube.com/watch?v=UUo5QDIfwiY","type":"youtube","youtubeId":"UUo5QDIfwiY"}],"links":[],"images":[],"descriptionSummaryHtml":"Designed the complete soundscape for the short film Richter, creating every sound from scratch using original field recordings and synthesis without relying on commercial sound libraries. Produced a custom sound library with organized metadata alongside a polished cinematic mix featuring vehicles, environmental effects, impacts, drones, alarms, and other designed assets. For the voices we had to come up with our own story…","descriptionHtml":"<p>Designed the complete soundscape for the short film *Richter*, creating every sound from scratch using original field recordings and synthesis without relying on commercial sound libraries. Produced a custom sound library with organized metadata alongside a polished cinematic mix featuring vehicles, environmental effects, impacts, drones, alarms, and other designed assets. For the voices we had to come up with our own story line.</p>\n<p>Note: Used AI for the female voice.</p>"},{"id":"sci-fi-vehicle-sound-design","title":"Sci-Fi Vehicle Sound Design","description":"Redesigned the audio for a gameplay sequence from WipeOut Omega Collection, creating original sci-fi vehicle, weapon, UI, collision, and environmental sound effects from scratch. Produced a cohesive game-ready mix and exported organized audio stems for the different sound categories.","hasMoreDescription":true,"context":"MTS2 - Digital Audio Workstations 2","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Vehicle Sound Design","Sound Design","Synthesizer Programming","Audio Mixing","Layering","Interactive Audio","Music Arrangement","Voice Acting"],"technologies":[],"tools":["Reaper","Vital"],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Technical Sound Designer","Audio Engineer","Music Producer"],"quality":"strong","qualityRank":4,"videos":[{"label":"Youtube","url":"https://youtu.be/mYsRoOPQuyg?si=xUSknjHeSh5V6LY9","type":"youtube","youtubeId":"mYsRoOPQuyg"}],"links":[],"images":[],"descriptionSummaryHtml":"Redesigned the audio for a gameplay sequence from *WipeOut Omega Collection*, creating original sci-fi vehicle, weapon, UI, collision, and environmental sound effects from scratch. Produced a cohesive game-ready mix and exported organized audio stems for the different sound categories.","descriptionHtml":"<p>Redesigned the audio for a gameplay sequence from *WipeOut Omega Collection*, creating original sci-fi vehicle, weapon, UI, collision, and environmental sound effects from scratch. Produced a cohesive game-ready mix and exported organized audio stems for the different sound categories.</p>\n<h5>Highlights</h5>\n<ul><li>Made a randomized collision machine using reapers sampler with tweak-able collision strength.</li><li>Made the vehicle sound using synthesis so that the speed of the vehicle could change the sound with a parameter.</li><li>Made Own Music using sample based aproach </li><li>Music Ducked on impact.</li><li>Arcade sounds in tune with music</li></ul>"},{"id":"weapon-sound-design-sci-fi","title":"Weapon Sound Design - Sci-fi","description":"Created sci-fi weapon sound effects for a game audio redesign project by combining synthesis, recorded sounds, and library samples. Produced multiple weapon variations and integrated them into gameplay scenes with ambience, reverb, foley, and a polished game-ready mix.","hasMoreDescription":true,"context":"MTS2 - Digital Audio Workstations 2","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Weapon Sound Design","Sound Design","Audio Mixing","Foley Recording","Synthesizer Programming","Layering"],"technologies":[],"tools":["Reaper","Vital"],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Technical Sound Designer","Audio Engineer"],"quality":"strong","qualityRank":4,"videos":[{"label":"L-Star","url":"https://youtu.be/4oZPqHV9on0?si=a2_KmFenakJJMrc4","type":"youtube","youtubeId":"4oZPqHV9on0"},{"label":"LaserKraftwerk","url":"https://youtu.be/416eBPZkhHI?si=l5wc91xe1A_IOXLV","type":"youtube","youtubeId":"416eBPZkhHI"}],"links":[],"images":[],"descriptionSummaryHtml":"Created sci-fi weapon sound effects for a game audio redesign project by combining synthesis, recorded sounds, and library samples. Produced multiple weapon variations and integrated them into gameplay scenes with ambience, reverb, foley, and a polished game-ready mix.","descriptionHtml":"<p>Created sci-fi weapon sound effects for a game audio redesign project by combining synthesis, recorded sounds, and library samples. Produced multiple weapon variations and integrated them into gameplay scenes with ambience, reverb, foley, and a polished game-ready mix.</p>\n<p>Guns: <a href=\"https://youtu.be/4oZPqHV9on0?si=RUmY5F6yksmWF9DE\" target=\"_blank\" rel=\"noreferrer\">Titanfall L-Star</a> &amp; <a href=\"https://youtu.be/416eBPZkhHI?si=NGBKgPjO5oYYqQMf\" target=\"_blank\" rel=\"noreferrer\">Wolfenstein LaserKraftwerk</a></p>\n<h4>Highlights</h4>\n<p>Created my own granular synth by stacking and delaying a bunch of reaper samplers. Used to make the electric fire sound in the LaserKraftwerk. Electric Fire render 003.wav</p>"},{"id":"adapta-solva-legacy","title":"Adapta Solva Legacy","description":"Created the sound design, music, and FMOD implementation for Adapta Solva, a Unity graduation project that I joined voluntarily during my first year of study. Produced 2 music tracks, implemented a simple dynamic music system, and handled the game's sound effects and audio integration using FMOD.","hasMoreDescription":false,"context":"Para Fauna","role":"Technical Sound Designer","status":"complete","collection":"Professional","disciplines":["Game Audio","Audio Implementation"],"skills":["Sound Design","FMOD Implementation","Dynamic Music","Music Production","Audio Implementation"],"technologies":["FMOD","Unity"],"tools":[],"concepts":[],"relevantFor":["Technical Sound Designer","Game Audio Designer","Sound Designer","Audio Implementer"],"quality":"good","qualityRank":3,"videos":[{"label":"Gameplay Video","url":"https://www.youtube.com/watch?v=P9J9BqLZnYg","type":"youtube","youtubeId":"P9J9BqLZnYg"}],"links":[{"label":"Song 1 - Grass Field at Night","url":"https://soundcloud.com/dreams_music/grass-field?si=caf2e7fac28e427d92561149b027c583&utm_source=clipboard&utm_medium=text&utm_campaign=social_sharing","type":"link","youtubeId":null},{"label":"Song 2 - Forrest Frogs","url":"https://soundcloud.com/dreams_music/forrest?si=9a850d5868664328a844707da302bea3&utm_source=clipboard&utm_medium=text&utm_campaign=social_sharing","type":"link","youtubeId":null},{"label":"Steam","url":"https://store.steampowered.com/app/2752680/Adapta_Solva_Legacy/","type":"link","youtubeId":null}],"images":[],"descriptionSummaryHtml":"Created the sound design, music, and FMOD implementation for <strong><a href=\"https://store.steampowered.com/app/2752680/Adapta_Solva_Legacy/\" target=\"_blank\" rel=\"noreferrer\">Adapta Solva</a></strong>, a Unity graduation project that I joined voluntarily during my first year of study. Produced 2 music tracks, implemented a simple dynamic music system, and handled the game&#039;s sound effects and audio integration using FMOD.","descriptionHtml":"<p>Created the sound design, music, and FMOD implementation for <strong><a href=\"https://store.steampowered.com/app/2752680/Adapta_Solva_Legacy/\" target=\"_blank\" rel=\"noreferrer\">Adapta Solva</a></strong>, a Unity graduation project that I joined voluntarily during my first year of study. Produced 2 music tracks, implemented a simple dynamic music system, and handled the game&#039;s sound effects and audio integration using FMOD.</p>"},{"id":"adapta-solva-linear","title":"Adapta Solva Linear","description":"This video demonstrates one of my procceses. Using linear audio as proof of concept. During this assignment I had already seeked out the Adapta Solva Legacy team and they where working on their game. This reaper video is a demonstration where I designed the sounds and added them under a gameplay video. These sounds where later adjusted based on feedback, exported and implimented using FMOD.","hasMoreDescription":false,"context":"MTS1 - Digital Audio Workstations","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Sound Design","Game Audio","Foley Recording","Audio Mixing","MIDI Composition","Dialogue Editing"],"technologies":[],"tools":["Reaper","ReaSynth","ReaSamplOmatic5000","TAL-NoiseMaker","Vital","Spitfire LABS","Spitfire BBC Symphony Orchestra Discover"],"concepts":[],"relevantFor":["Sound Designer","Technical Sound Designer","Game Audio Designer","Audio Engineer"],"quality":"good","qualityRank":3,"videos":[],"links":[],"images":[],"descriptionSummaryHtml":"This video demonstrates one of my procceses. Using linear audio as proof of concept. During this assignment I had already seeked out the <a href=\"?filter=projects%3AAdapta+Solva+Legacy\">Adapta Solva Legacy</a> team and they where working on their game. This reaper video is a demonstration where I designed the sounds and added them under a gameplay video. These sounds where later adjusted based on feedback, exported and implimented using FMOD.","descriptionHtml":"<p>This video demonstrates one of my procceses. Using linear audio as proof of concept. During this assignment I had already seeked out the <a href=\"?filter=projects%3AAdapta+Solva+Legacy\">Adapta Solva Legacy</a> team and they where working on their game. This reaper video is a demonstration where I designed the sounds and added them under a gameplay video. These sounds where later adjusted based on feedback, exported and implimented using FMOD.</p>"},{"id":"the-investigation","title":"The Investigation","description":"Created the FMOD audio direction and implementation for The Investigation, a noir detective game focused on atmosphere and environmental storytelling. Built dynamic ambience, spatialized point sounds, encounter monologues, dialogue playback logic, reverb, randomized sound behaviour, and a structured mixer with separate music, voice, and effects controls.","hasMoreDescription":true,"context":"MTS3 - Middleware 1","role":"Technical Sound Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Audio Implementation"],"skills":["FMOD Implementation","Dynamic Ambience Design","Spatial Audio","Interactive Dialogue Systems","Audio Mixing","Audio Randomization"],"technologies":["FMOD"],"tools":[],"concepts":[],"relevantFor":["Technical Sound Designer","Game Audio Designer","Audio Implementer","Sound Designer"],"quality":"good","qualityRank":3,"videos":[{"label":"Youtube","url":"https://youtu.be/2L366rKQRls?si=hwtsv1L-kqxg-cXA","type":"youtube","youtubeId":"2L366rKQRls"}],"links":[],"images":[],"descriptionSummaryHtml":"Created the FMOD audio direction and implementation for *The Investigation*, a noir detective game focused on atmosphere and environmental storytelling. Built dynamic ambience, spatialized point sounds, encounter monologues, dialogue playback logic, reverb, randomized sound behaviour, and a structured mixer with separate music, voice, and effects controls.","descriptionHtml":"<p>Created the FMOD audio direction and implementation for *The Investigation*, a noir detective game focused on atmosphere and environmental storytelling. Built dynamic ambience, spatialized point sounds, encounter monologues, dialogue playback logic, reverb, randomized sound behaviour, and a structured mixer with separate music, voice, and effects controls.</p>\n<h4>Highlights</h4>\n<ul><li>Menu Open Mixer Snapshot</li><li>Change Ambience depending on height</li><li>Audio Synced with in game video</li><li>Random Audio Encounters in Ambience</li></ul>"},{"id":"anno-gameplay-horizontal-playlists-in-wwise","title":"Anno Gameplay Horizontal Playlists in Wwise","description":"Designed and implemented adaptive music systems in Wwise for Anno 1800 using horizontal resequencing techniques. Built separate playlists for calm and high-intensity gameplay with seamless looping, randomization, and musical variation to reduce repetition during extended play sessions.","hasMoreDescription":false,"context":"MTS4 - Music for Games","role":"Interactive Music Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Interactive Music"],"skills":["Wwise Music Integration","Horizontal Resequencing","Interactive Music Design","Music Systems Design"],"technologies":["Wwise"],"tools":[],"concepts":["Adaptive Music"],"relevantFor":["Interactive Music Designer","Technical Sound Designer","Game Audio Designer","Audio Implementer"],"quality":"medium","qualityRank":2,"videos":[{"label":"A Suitable Suitor","url":"https://youtu.be/TzBuFCxi0qU","type":"youtube","youtubeId":"TzBuFCxi0qU"},{"label":"Ominous Violin","url":"https://youtu.be/J7v4WC7AqYY?si=31us1xOlLW6ioJNa","type":"youtube","youtubeId":"J7v4WC7AqYY"}],"links":[],"images":[],"descriptionSummaryHtml":"Designed and implemented adaptive music systems in Wwise for *Anno 1800* using horizontal resequencing techniques. Built separate playlists for calm and high-intensity gameplay with seamless looping, randomization, and musical variation to reduce repetition during extended play sessions.","descriptionHtml":"<p>Designed and implemented adaptive music systems in Wwise for *Anno 1800* using horizontal resequencing techniques. Built separate playlists for calm and high-intensity gameplay with seamless looping, randomization, and musical variation to reduce repetition during extended play sessions.</p>"},{"id":"car","title":"Car","description":"A 3D model of an old Volkswagen-style van converted into a small camper. Next to it a bathtub, some logs and some plant pots. The model and UV maps were created in Blender, with textures produced in Photoshop.","hasMoreDescription":false,"context":"MTS2 - 3D 1","role":"3D Artist","status":"complete","collection":"Education","disciplines":["3D","Game Art"],"skills":["3D Modelling","Texturing","UV Unwrapping"],"technologies":[],"tools":["Blender","Photoshop"],"concepts":[],"relevantFor":["3D Artist"],"quality":"medium","qualityRank":2,"videos":[],"links":[{"label":"Sketchfab model","url":"https://sketchfab.com/3d-models/dae-5-finished-props-forrest-loner-ba8a94c25ae34a53929a8eedb45f4d81","type":"link","youtubeId":null}],"images":[{"target":"Car_Front.png","label":"Car_Front","type":"image","url":"../assets/evidence/444c05821ae9fc60.png"},{"target":"Car_Back.png","label":"Car_Back","type":"image","url":"../assets/evidence/a5b2069175ae094e.png"}],"descriptionSummaryHtml":"A 3D model of an old Volkswagen-style van converted into a small camper. Next to it a bathtub, some logs and some plant pots. The model and UV maps were created in Blender, with textures produced in Photoshop.","descriptionHtml":"<p>A 3D model of an old Volkswagen-style van converted into a small camper. Next to it a bathtub, some logs and some plant pots. The model and UV maps were created in Blender, with textures produced in Photoshop.</p>"},{"id":"cropout","title":"Cropout","description":"Implemented the complete audio experience for Epic Games' Cropout sample project in Unreal Engine 5, focusing on scalable audio architecture, interactive mixing, and custom spatial audio solutions. The project included ambience, sound effects, UI audio, dynamic mixing, and reusable Blueprint systems designed to support a top-down strategy game.","hasMoreDescription":true,"context":"MTS3 - Audio Implimentation 2","role":"Technical Sound Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Audio Implementation"],"skills":["Unreal Engine Audio","Blueprint Programming","Audio Systems Design","Spatial Audio","Audio Mixing","Tool Development"],"technologies":["Unreal Engine 5","Blueprints","MetaSounds"],"tools":["Audio Insights"],"concepts":[],"relevantFor":["Technical Sound Designer","Game Audio Programmer","Unreal Engine Developer","Sound Designer"],"quality":"medium","qualityRank":2,"videos":[{"label":"YouTube","url":"https://youtu.be/GTCGhrOoxfg","type":"youtube","youtubeId":"GTCGhrOoxfg"}],"links":[],"images":[],"descriptionSummaryHtml":"Implemented the complete audio experience for Epic Games&#039; <strong>Cropout</strong> sample project in Unreal Engine 5, focusing on scalable audio architecture, interactive mixing, and custom spatial audio solutions. The project included ambience, sound effects, UI audio, dynamic mixing, and reusable Blueprint systems designed to support a top-down strategy game.","descriptionHtml":"<p>Implemented the complete audio experience for Epic Games&#039; <strong>Cropout</strong> sample project in Unreal Engine 5, focusing on scalable audio architecture, interactive mixing, and custom spatial audio solutions. The project included ambience, sound effects, UI audio, dynamic mixing, and reusable Blueprint systems designed to support a top-down strategy game.</p>\n<p>A major technical contribution was the development of a custom <strong>2D top-down attenuation system</strong>. Traditional 3D attenuation did not provide the desired behaviour for the game&#039;s elevated camera, so a custom solution was implemented that dynamically adjusted both panning and gain based on the camera&#039;s angle and height relative to audio sources. As the camera zoomed out, sounds remained intelligible over larger distances, while zooming in naturally reduced the audible range, creating a more consistent listening experience.</p>\n<p>The environmental ambience was also made fully adaptive by linking its behaviour to the camera height. As the player zoomed between gameplay perspectives, the ambience responded dynamically, reinforcing the sense of scale while maintaining a balanced mix throughout the game.</p>\n<p>Beyond the custom attenuation system, the project explored Unreal Engine&#039;s modern audio pipeline through sound classes, submixes, effects, Audio Insights, Blueprint-based implementation, and interactive mixing techniques. The implementation emphasized reusable systems, debugging workflows, and maintainable project architecture while balancing technical correctness with an engaging player experience.</p>"},{"id":"immersive-soundscapes","title":"Immersive Soundscapes","description":"Created an immersive horror-themed soundscape and produced channel-based, ambisonic, binaural, object-based, and Wwise spatial audio mixes. The project demonstrated sound design, spatial positioning, multiformat mixing, rendering, and organized audio production workflows.","hasMoreDescription":false,"context":"MTS4 - Sound 4","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio"],"skills":["Sound Design","Spatial Audio","Surround Mixing","Ambisonics","Binaural Audio","Audio Implementation"],"technologies":["Dolby Atmos","Wwise"],"tools":["Reaper","IEM Plugin Suite","dearVR Micro","dearVR Ambi Micro","Atmoky Ears","Fiedler Dolby Atmos Composer Essential"],"concepts":[],"relevantFor":["Sound Designer","Spatial Audio Designer","Mix Engineer","Audio Engineer","Technical Sound Designer"],"quality":"medium","qualityRank":2,"videos":[],"links":[],"images":[{"target":"Reaper.jpg","label":"Reaper","type":"image","url":"../assets/evidence/cb4dd7f8348b457e.jpg"}],"descriptionSummaryHtml":"Created an immersive horror-themed soundscape and produced channel-based, ambisonic, binaural, object-based, and Wwise spatial audio mixes. The project demonstrated sound design, spatial positioning, multiformat mixing, rendering, and organized audio production workflows.","descriptionHtml":"<p>Created an immersive horror-themed soundscape and produced channel-based, ambisonic, binaural, object-based, and Wwise spatial audio mixes. The project demonstrated sound design, spatial positioning, multiformat mixing, rendering, and organized audio production workflows.</p>"},{"id":"lego-smart-play-sound-design","title":"LEGO - Smart Play Sound Design","description":"Contributed sound design to LEGO SMART Play, creating sounds within its synth-based audio system. Worked within the project's existing audio framework to design sounds suited to the interactive experience.","hasMoreDescription":true,"context":"Internship","role":"Sound Designer","status":"complete","collection":"Professional","disciplines":["Game Audio","Interactive Audio"],"skills":["Sound Design","Synthesizer Programming","Interactive Audio"],"technologies":[],"tools":[],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Technical Sound Designer"],"quality":"medium","qualityRank":2,"videos":[],"links":[],"images":[{"target":"LEGO.jpg","label":"LEGO","type":"image","url":"../assets/evidence/2d987d06dcc4be90.jpg"}],"descriptionSummaryHtml":"Contributed sound design to <strong>LEGO SMART Play</strong>, creating sounds within its synth-based audio system. Worked within the project&#039;s existing audio framework to design sounds suited to the interactive experience.","descriptionHtml":"<p>Contributed sound design to <strong>LEGO SMART Play</strong>, creating sounds within its synth-based audio system. Worked within the project&#039;s existing audio framework to design sounds suited to the interactive experience.</p>\n<p>*For more information, reach out to designtalent@lego.com.</p>"},{"id":"luna","title":"Luna","description":"Reworked the audio implementation of Luna, an educational Unity game used to teach children how to write, replacing its existing native audio solution with a clean FMOD integration. Worked within an existing codebase and development workflow to remove legacy audio functionality, integrate and version the new audio system through Perforce, and redesign the project's soundscape while preserving existing functionality.","hasMoreDescription":false,"context":"MTS4 - Sound Integration 2","role":"Technical Sound Designer","status":"complete","collection":"Education","disciplines":["Game Audio","Audio Programming"],"skills":["FMOD Integration","Game Audio Implementation","Audio Programming","Sound Design","Unity Development"],"technologies":["Unity","FMOD"],"tools":["Perforce"],"concepts":[],"relevantFor":["Technical Sound Designer","Audio Programmer","Game Audio Designer","Audio Implementer"],"quality":"medium","qualityRank":2,"videos":[{"label":"Demo","url":"https://youtu.be/SN4Ivl6NoKU","type":"youtube","youtubeId":"SN4Ivl6NoKU"}],"links":[],"images":[{"target":"Luna.png","label":"Luna","type":"image","url":"../assets/evidence/61de94e0dd326022.png"}],"descriptionSummaryHtml":"Reworked the audio implementation of <a href=\"https://play.google.com/store/apps/details?id=be.diekeure.luna\" target=\"_blank\" rel=\"noreferrer\"><strong>Luna</strong></a>, an educational Unity game used to teach children how to write, replacing its existing native audio solution with a clean FMOD integration. Worked within an existing codebase and development workflow to remove legacy audio functionality, integrate and version the new audio system through Perforce, and redesign the project&#039;s soundscape while preserving existing functionality.","descriptionHtml":"<p>Reworked the audio implementation of <a href=\"https://play.google.com/store/apps/details?id=be.diekeure.luna\" target=\"_blank\" rel=\"noreferrer\"><strong>Luna</strong></a>, an educational Unity game used to teach children how to write, replacing its existing native audio solution with a clean FMOD integration. Worked within an existing codebase and development workflow to remove legacy audio functionality, integrate and version the new audio system through Perforce, and redesign the project&#039;s soundscape while preserving existing functionality.</p>"},{"id":"music-composition-and-vertical-re-orchestration","title":"Music composition and vertical re-orchestration","description":"Composed and implemented an adaptive music system featuring original music with multiple interactive variations. Combined horizontal resequencing, vertical re-orchestration, MIDI-driven drum playback, and Wwise samplers to create a dynamic soundtrack with seamless transitions, randomized musical layers, and reduced memory usage.","hasMoreDescription":false,"context":"MTS4 - Music for Games","role":"Composer","status":"complete","collection":"Education","disciplines":["Game Audio","Interactive Music"],"skills":["Music Composition","Interactive Music","Vertical Remixing","Horizontal Resequencing","MIDI Programming","Adaptive Music Design"],"technologies":["Wwise"],"tools":["Reaper"],"concepts":[],"relevantFor":["Game Composer","Technical Sound Designer","Interactive Music Designer","Game Audio Designer"],"quality":"medium","qualityRank":2,"videos":[{"label":"YouTube","url":"https://youtu.be/0WiEICj7iW0","type":"youtube","youtubeId":"0WiEICj7iW0"}],"links":[],"images":[],"descriptionSummaryHtml":"Composed and implemented an adaptive music system featuring original music with multiple interactive variations. Combined horizontal resequencing, vertical re-orchestration, MIDI-driven drum playback, and Wwise samplers to create a dynamic soundtrack with seamless transitions, randomized musical layers, and reduced memory usage.","descriptionHtml":"<p>Composed and implemented an adaptive music system featuring original music with multiple interactive variations. Combined horizontal resequencing, vertical re-orchestration, MIDI-driven drum playback, and Wwise samplers to create a dynamic soundtrack with seamless transitions, randomized musical layers, and reduced memory usage.</p>"},{"id":"spatialization-practical-exam","title":"Spatialization Practical Exam","description":"Completed a time-limited practical exam by creating an immersive spatial audio redesign for a gameplay scene from Senua's Saga: Hellblade II. Within the exam session, combined binaurally spatialized inner voices with third-order Ambisonics ambience and sound effects, producing both a stereo binaural headphone mix and a third-order Ambisonics ambience mix prepared for game-engine implementation.","hasMoreDescription":true,"context":"MTS4 - Sound 4","role":"Spatial Audio Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Spatial Audio","Ambisonics","Binaural Audio","Sound Design","Immersive Audio Mixing","Field Recording"],"technologies":[],"tools":["Reaper","Sennheiser AMBEO"],"concepts":[],"relevantFor":["Spatial Audio Designer","Sound Designer","Technical Sound Designer","Game Audio Designer","Audio Engineer"],"quality":"medium","qualityRank":2,"videos":[],"links":[],"images":[],"descriptionSummaryHtml":"Completed a time-limited practical exam by creating an immersive spatial audio redesign for a gameplay scene from *Senua&#039;s Saga: Hellblade II*. Within the exam session, combined binaurally spatialized inner voices with third-order Ambisonics ambience and sound effects, producing both a stereo binaural headphone mix and a third-order Ambisonics ambience mix prepared for game-engine implementation.","descriptionHtml":"<p>Completed a time-limited practical exam by creating an immersive spatial audio redesign for a gameplay scene from *Senua&#039;s Saga: Hellblade II*. Within the exam session, combined binaurally spatialized inner voices with third-order Ambisonics ambience and sound effects, producing both a stereo binaural headphone mix and a third-order Ambisonics ambience mix prepared for game-engine implementation.</p>\n<h5>Techniques Used</h5>\n<p>Used large moving granular chunks for the voices.</p>"},{"id":"stylised-loop-hero","title":"Stylised, Loop Hero","description":"Developed a complete sound palette and sound design bible for LoopHero, defining a cohesive audio identity independent of the original soundtrack. Wrote a new soundtrack. Redesigned the game's menu and gameplay audio with original processed sounds, synthesis, and layered recordings, and presented the creative vision as a sound lead pitch.","hasMoreDescription":true,"context":"MTS3 - Sound 3","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Sound Palette Design","Sound Design","Audio Direction","Audio Mixing","Layering","Synthesizer Programming","Music Composition"],"technologies":[],"tools":["Reaper"],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Audio Director","Audio Engineer","Composer"],"quality":"medium","qualityRank":2,"videos":[{"label":"YouTube","url":"https://youtu.be/7gWeEwF1BzM","type":"youtube","youtubeId":"7gWeEwF1BzM"}],"links":[],"images":[],"descriptionSummaryHtml":"Developed a complete sound palette and sound design bible for <strong>LoopHero</strong>, defining a cohesive audio identity independent of the original soundtrack. Wrote a new soundtrack. Redesigned the game&#039;s menu and gameplay audio with original processed sounds, synthesis, and layered recordings, and presented the creative vision as a sound lead pitch.","descriptionHtml":"<p>Developed a complete sound palette and sound design bible for <strong>LoopHero</strong>, defining a cohesive audio identity independent of the original soundtrack. Wrote a new soundtrack. Redesigned the game&#039;s menu and gameplay audio with original processed sounds, synthesis, and layered recordings, and presented the creative vision as a sound lead pitch.</p>\n<h5>Highlights</h5>\n<ul><li>During slow mode a half time version of the music plays. This is always a great slow down effect that you can crossfade right into.</li></ul>"},{"id":"to-bee-or-not-to-bee","title":"To Bee or Not To Bee","description":"Created the sound design and music for ToBeeOrNotToBee, a Unity game about a bee defending its hive. Produced and integrated the game's audio using Reaper and Unity.","hasMoreDescription":false,"context":"personal","role":"Sound Designer","status":"complete","collection":"Game Jam","disciplines":["Game Audio","Music"],"skills":["Sound Design","Music Composition","Audio Mixing","Game Audio"],"technologies":["Unity"],"tools":["Reaper"],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Composer"],"quality":"medium","qualityRank":2,"videos":[{"label":"Trailer","url":"https://youtu.be/t462maRmqfc?si=HDWwYWF8F1_SVRrl","type":"youtube","youtubeId":"t462maRmqfc"}],"links":[{"label":"Music","url":"https://soundcloud.com/dreams_music/tobeeornottobee-1","type":"link","youtubeId":null},{"label":"Itch","url":"https://ieva-sucila.itch.io/tobeeornottobee","type":"link","youtubeId":null}],"images":[],"descriptionSummaryHtml":"Created the sound design and music for <strong>ToBeeOrNotToBee</strong>, a Unity game about a bee defending its hive. Produced and integrated the game&#039;s audio using Reaper and Unity.","descriptionHtml":"<p>Created the sound design and music for <strong>ToBeeOrNotToBee</strong>, a Unity game about a bee defending its hive. Produced and integrated the game&#039;s audio using Reaper and Unity.</p>"},{"id":"tony-pigeon-pro-skater","title":"Tony Pigeon Pro Skater","description":"Created the sound design and music for Tony Pigeon Pro Skater, a game jam project built around endless-runner gameplay where the player jumps over obstacles and performs aerial tricks through button combinations.","hasMoreDescription":true,"context":"","role":"Sound Designer","status":"complete","collection":"Game Jam","disciplines":["Game Audio","Music"],"skills":["Sound Design","Music Composition","Audio Mixing"],"technologies":[],"tools":[],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Composer"],"quality":"medium","qualityRank":2,"videos":[],"links":[{"label":"Itch","url":"https://kayahx.itch.io/kikkerwertjes","type":"link","youtubeId":null},{"label":"Song","url":"https://soundcloud.com/dreams_music/sets/tony-pigeons-pro-skater-3-soundtrack?si=d603f70dec68432c868bb99111f04eb6&utm_source=clipboard&utm_medium=text&utm_campaign=social_sharing","type":"link","youtubeId":null}],"images":[{"target":"TonyPigeon.png","label":"TonyPigeon","type":"image","url":"../assets/evidence/bd4024b96d90b229.png"}],"descriptionSummaryHtml":"Created the sound design and music for <strong><a href=\"?filter=projects%3ATony+Pigeon+Pro+Skater\">Tony Pigeon Pro Skater</a></strong>, a game jam project built around endless-runner gameplay where the player jumps over obstacles and performs aerial tricks through button combinations.","descriptionHtml":"<p>Created the sound design and music for <strong><a href=\"?filter=projects%3ATony+Pigeon+Pro+Skater\">Tony Pigeon Pro Skater</a></strong>, a game jam project built around endless-runner gameplay where the player jumps over obstacles and performs aerial tricks through button combinations.</p>\n<h5>Highlights</h5>\n<ul><li>A half time version of the song plays during slow mo time. The original song pitches down with a crossfade into it. This creates a great slow mo transition.</li></ul>"},{"id":"weapon-sound-design-realistic","title":"Weapon Sound Design - Realistic","description":"Created weapon sound effects for a game audio redesign project by combining synthesis, recorded sounds, and library samples. Produced multiple weapon variations and integrated them into gameplay scenes with ambience, reverb, foley, and a polished game-ready mix.","hasMoreDescription":true,"context":"MTS2 - Digital Audio Workstations 2","role":"Sound Designer","status":"complete","collection":"Education","disciplines":["Audio","Game Audio"],"skills":["Weapon Sound Design","Sound Design","Audio Mixing","Foley Recording","Synthesizer Programming","Layering"],"technologies":[],"tools":["Reaper","Vital"],"concepts":[],"relevantFor":["Sound Designer","Game Audio Designer","Technical Sound Designer","Audio Engineer"],"quality":"medium","qualityRank":2,"videos":[{"label":"M1911","url":"https://youtu.be/zfYo6-TjNTU","type":"youtube","youtubeId":"zfYo6-TjNTU"},{"label":"M16A4","url":"https://youtu.be/LVbpgv8W1RM","type":"youtube","youtubeId":"LVbpgv8W1RM"}],"links":[],"images":[],"descriptionSummaryHtml":"Created weapon sound effects for a game audio redesign project by combining synthesis, recorded sounds, and library samples. Produced multiple weapon variations and integrated them into gameplay scenes with ambience, reverb, foley, and a polished game-ready mix.","descriptionHtml":"<p>Created weapon sound effects for a game audio redesign project by combining synthesis, recorded sounds, and library samples. Produced multiple weapon variations and integrated them into gameplay scenes with ambience, reverb, foley, and a polished game-ready mix.</p>\n<p>Guns: M1911 &amp; M16A4</p>\n<p>The biggest challenge was getting the relative power of the guns down. The M16A4 is much stronger and I wanted to convey this with sound. I achieved this at the cost of having the M1911 sound less strong.</p>"},{"id":"house-diorama","title":"House Diorama","description":"A diorama of a mountain house with a stone path, a tree, a chicken coop and a food stall. Also includes the car and props of Car. The model and UV maps were created in Blender, with textures produced in Photoshop.","hasMoreDescription":false,"context":"MTS2 - 3D 1","role":"3D Artist","status":"complete","collection":"Education","disciplines":["3D","Game Art"],"skills":["3D Modelling","Texturing","UV Unwrapping"],"technologies":[],"tools":["Blender","Photoshop"],"concepts":[],"relevantFor":["3D Artist"],"quality":"beginner","qualityRank":1,"videos":[],"links":[{"label":"Sketchfab Model","url":"https://skfb.ly/pqpYr","type":"link","youtubeId":null}],"images":[{"target":"1ISP17E_Peene_Matthias_BeautyShot_00.png","label":"1ISP17E_Peene_Matthias_BeautyShot_00","type":"image","url":"../assets/evidence/c093412f1410b89b.png"},{"target":"1ISP17E_Peene_Matthias_BeautyShot_01.png","label":"1ISP17E_Peene_Matthias_BeautyShot_01","type":"image","url":"../assets/evidence/3321ab50f72d6ea2.png"},{"target":"1ISP17E_Peene_Matthias_BeautyShot_02.png","label":"1ISP17E_Peene_Matthias_BeautyShot_02","type":"image","url":"../assets/evidence/f981fe87974101c6.png"}],"descriptionSummaryHtml":"A diorama of a mountain house with a stone path, a tree, a chicken coop and a food stall. Also includes the car and props of <a href=\"?filter=projects%3ACar\">Car</a>. The model and UV maps were created in Blender, with textures produced in Photoshop.","descriptionHtml":"<p>A diorama of a mountain house with a stone path, a tree, a chicken coop and a food stall. Also includes the car and props of <a href=\"?filter=projects%3ACar\">Car</a>. The model and UV maps were created in Blender, with textures produced in Photoshop.</p>"}];
